"=== RAM GROUPED BY APP (top 15) ==="
Get-Process | Group-Object ProcessName | ForEach-Object {
  [PSCustomObject]@{ App=$_.Name; Procs=$_.Count; RAM_MB=[math]::Round((($_.Group | Measure-Object WS -Sum).Sum)/1MB) }
} | Sort-Object RAM_MB -Descending | Select-Object -First 15 | Format-Table -AutoSize | Out-String -Width 200
""
"=== CURRENT CPU (2s sample, top 10) ==="
$s1=@{}; Get-Process | ForEach-Object { $s1[$_.Id]=$_.CPU }
Start-Sleep -Seconds 2
Get-Process | ForEach-Object {
  if ($s1.ContainsKey($_.Id) -and $s1[$_.Id] -ne $null -and $_.CPU -ne $null) {
    $d = $_.CPU - $s1[$_.Id]
    if ($d -gt 0) { [PSCustomObject]@{ Name=$_.ProcessName; Pct=[math]::Round(($d/2/8)*100,1) } }
  }
} | Sort-Object Pct -Descending | Select-Object -First 10 | Format-Table -AutoSize | Out-String -Width 200
""
"=== WSL memory config ==="
if (Test-Path "$env:USERPROFILE\.wslconfig") { Get-Content "$env:USERPROFILE\.wslconfig" } else { "(no .wslconfig - WSL2 may claim up to 50% of RAM = ~7.8 GB)" }
""
"=== Pagefile ==="
Get-CimInstance Win32_PageFileUsage | Select-Object Name,@{n='AllocMB';e={$_.AllocatedBaseSize}},@{n='PeakMB';e={$_.PeakUsage}},@{n='CurrentMB';e={$_.CurrentUsage}} | Format-Table -AutoSize | Out-String -Width 200

"=== CPU over 6s, grouped by app (top 12) ==="
$s=@{}; Get-Process | ForEach-Object { if($_.CPU -ne $null){$s[$_.Id]=$_.CPU} }
Start-Sleep -Seconds 6
$rows = Get-Process | ForEach-Object {
  if ($s.ContainsKey($_.Id) -and $_.CPU -ne $null) { [PSCustomObject]@{ App=$_.ProcessName; D=($_.CPU - $s[$_.Id]) } }
}
$rows | Group-Object App | ForEach-Object {
  [PSCustomObject]@{ App=$_.Name; CPU_Pct=[math]::Round(((($_.Group|Measure-Object D -Sum).Sum)/6/8)*100,1) }
} | Where-Object {$_.CPU_Pct -gt 0.3} | Sort-Object CPU_Pct -Descending | Select-Object -First 12 | Format-Table -AutoSize | Out-String -Width 200
""
"=== TOP DISK I/O (cumulative MB read+written since process start) ==="
Get-Process | Where-Object {$_.TotalProcessorTime -ne $null} | ForEach-Object {
  $io = (Get-CimInstance Win32_Process -Filter "ProcessId=$($_.Id)" -ErrorAction SilentlyContinue)
  if ($io) { [PSCustomObject]@{ App=$_.ProcessName; IO_MB=[math]::Round(($io.ReadTransferCount + $io.WriteTransferCount)/1MB) } }
} | Group-Object App | ForEach-Object {
  [PSCustomObject]@{ App=$_.Name; IO_MB=($_.Group|Measure-Object IO_MB -Sum).Sum }
} | Sort-Object IO_MB -Descending | Select-Object -First 12 | Format-Table -AutoSize | Out-String -Width 200

"=== python / node processes ==="
Get-CimInstance Win32_Process -Filter "Name='python.exe' OR Name='pythonw.exe' OR Name='node.exe'" |
  Select-Object ProcessId,Name,@{n='RAM_MB';e={[math]::Round($_.WorkingSetSize/1MB)}},@{n='IO_MB';e={[math]::Round(($_.ReadTransferCount+$_.WriteTransferCount)/1MB)}},@{n='Cmd';e={ if($_.CommandLine){$_.CommandLine.Substring(0,[Math]::Min(95,$_.CommandLine.Length))}else{'-'} }} |
  Sort-Object IO_MB -Descending | Format-Table -AutoSize | Out-String -Width 220
""
"=== sync / scanner agents running ==="
'OneDrive','GoogleDriveFS','AdobeCollabSync','CrashPlanService','CrashPlanDesktop','MsMpEng','MsSense','SearchIndexer' | ForEach-Object {
  $p = Get-Process $_ -ErrorAction SilentlyContinue
  if ($p) { "{0,-20} procs={1,-3} RAM={2,6} MB" -f $_, @($p).Count, [math]::Round((($p|Measure-Object WS -Sum).Sum)/1MB) }
}

